/** A page of results. The API's PagedResultOf* types all have this shape. */
export interface PagedResult<T> {
  items: T[];
  page: number;
  pageSize: number;
  totalCount: number;
}

export type ReactionCounts = { [key in ReactionType]?: number };

/** The heat map's query: a box (minLon,minLat,maxLon,maxLat), the map zoom, and optional filters. */
export interface HeatmapQuery {
  bbox: string;
  zoom?: number;
  from?: string;
  to?: string;
  categories?: string;
  hours?: string;
  days?: HeatmapDays;
  vehicleTypes?: string;
  make?: string;
  model?: string;
  colours?: string;
  light?: HeatmapLight;
  schoolRun?: boolean;
  reported?: boolean;
  videoOnly?: boolean;
}

/**
 * RFC 7807 problem details, as the API's ModuleExceptionHandler writes them, with its extra fields. Wider than the
 * generated ProblemDetails, which doesn't know the extensions.
 */
export interface ProblemDetails {
  type?: string;
  title?: string;
  status?: number;
  detail?: string;
  code?: string;
  errors?: Record<string, string[]>;
  /** daily_limit: when the allowance starts again. */
  resetsAt?: string;
  limit?: number;
}
